const readline = require('readline').createInterface({
    input: process.stdin,
    output: process.stdout
});

readline.on('line', (line) => {
    const [n, m, a, b] = line.split(' ').map(Number);
    const fullTickets = Math.floor(n / m);
    const remainingRides = n % m;
    const cost1 = fullTickets * b + remainingRides * a;
    const cost2 = (fullTickets + 1) * b;
    const cost3 = n * a;
    console.log(Math.min(cost1, cost2, cost3));
    readline.close();
});
```

