```javascript
const readline = require('readline');
const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

rl.on('line', (line) => {
  const [n, m, a, b] = line.split(' ').map(Number);
  let minCost = Infinity;
  const maxMTickets = Math.ceil(n / m);
  for (let i = 0; i <= maxMTickets; i++) {
    const ridesLeft = n - i * m;
    const cost = i * b + (ridesLeft > 0 ? ridesLeft * a : 0);
    if (cost < minCost) minCost = cost;
  }
  console.log(minCost);
  rl.close();
});
```

